def make(fid):
    d=json.load(open(SRC%fid,encoding='utf-8'))
    d['sections']=[s for s in d['sections'] if s['id'] not in('prompty','check')]
    stuck=[]
    for s in d['sections']:
        s['blocks']=[b for b in s['blocks'] if b['type'] not in('prompt','builder') and not(b['type']=='note' and re.match(r'Как (с|в) |Бытов',b.get('title','')))]
        if s['id']=='zadanie':
            t=[b for b in s['blocks'] if b['type']=='task'][0]; stuck=t.get('stuck',[])
    d['sections']=[s for s in d['sections'] if s['id']!='zadanie']
    d['lead']=re.sub(r'\s*После методички.*?(?=(?:\s[A-ZА-Я][^<]*)?$)','',d['lead'],flags=re.S) if False else d['lead']
    out=[]
    for s in d['sections']:
        if s['id']=='faq':
            items=s['blocks'][0]['items']; new=[]
            for q,a in stuck:
                q2='Что делать, если '+q[0].lower()+q[1:].replace('Если ','',1)+'?'
                a2=a[3:] if a.startswith('то ') else a; a2=a2[0].upper()+a2[1:]+('' if a2.endswith('.') else '.')
                new.append([q2,a2])
            s['blocks'][0]['items']=(new+items)[:9]
        if s['id']=='primery': s['title']='Пример'; s['nav']='Пример'
        out.append(s)
        if s['id']=='primery':
            a=AI[fid]
            out.append({'id':'ai','nav':'В паре с нейронкой','title':'В паре с нейронкой','blocks':[
              {'type':'ai','give':a['give'],'keep':a['keep'],'mistake':a['mistake'],'steps':[{'t':t,'d':dd} for t,dd in a['steps']]},
              {'type':'note','title':'Почему здесь нет готовых промптов','text':'Агент пишет запрос под твой план и твои цифры. Чужой готовый промпт подходит чужому проекту, а исходные данные знаешь только ты. Поэтому ты рассказываешь агенту, что нужно, а он оформляет запрос.'}]})
    d['sections']=out
    d['quiz']=QUIZ[fid]
    s=json.dumps(d,ensure_ascii=False)
    for a,b in [('«Морошки»','бренда'),('«Морошка»','бренд'),('«Морошку»','бренд'),('Морошки','бренда'),('Морошка','бренд'),('Морошку','бренд'),
                ('бутылку','продукт'),('бутылка','продукт'),('бутылки','продукта'),('бутылке','продукте'),('Бутылку','Продукт'),
                ('Промптер MJ','Промптер картинок'),
                ('методичкой','статьёй'),('методичке','статье'),('методичку','статью'),('методички','статьи'),('методичка','статья'),('методичек','статей'),('методичкам','статьям'),
                ('по уроку 2.3','в модуле 2'),('в уроке 2.3','в модуле 2'),('по урокам курса','по модулям курса'),
                ('Сгенерируй продукт по промпту из раздела «Промпты», скачай лучший вариант','Сгенерируй пробный кадр продукта своего бренда, выбери лучший вариант'),('поменяй крышку промптом из раздела «Промпты»','поменяй крышку одной правкой'),('промпты урока работают так же','запросы работают так же'),('На первые уроки — да','На первые модули — да'),('Уроки до модуля 2 — да','Модули до второго — да'),('Для большинства студентов Syntx','Для большинства Syntx'),('Студентка','Ты'),('студентка','ты'),
                ('студент отвечает и сам выбирает','ты отвечаешь и сам выбираешь')]:
        s=s.replace(a,b)
    for n,name in ART.items():
        s=s.replace('урок '+n,'статья '+name).replace('Урок '+n,'Статья '+name).replace('урока '+n,'статьи '+name).replace('уроке '+n,'статье '+name)
    s=re.sub(r'(«[^»]+») \1',r'\1',s)
    s=s.replace('если если','если')
    return postpay2(fid,postpay(fid,json.loads(s)))
